"""Grades."""


def average(scores):
    if not scores:
        return None
    return sum(scores) / len(scores)


def best_student(table):
    return max(table, key=lambda name: average(table[name]) or 0)


def report(table):
    return {"best": best_student(table), "class_average": average([s for v in table.values() for s in v])}

